package org.joda.time.format;

import java.io.*;
import java.io.IOException;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.time.Chronology;
import org.joda.time.DateTime;
import org.joda.time.DateTimeUtils;
import org.joda.time.DateTimeZone;
import org.joda.time.Instant;
import org.joda.time.LocalDate;
import org.joda.time.LocalDateTime;
import org.joda.time.LocalTime;
import org.joda.time.MutableDateTime;
import org.joda.time.ReadWritableInstant;
import org.joda.time.ReadableInstant;
import org.joda.time.ReadablePartial;
import org.joda.time.format.DateTimeFormatterBuilder;
import org.joda.time.format.DateTimeParser;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class DateTimeFormatter_parseInto_TriageGen2Test {

    @Test
    public void testParseInto_NullInstant_ThrowsException() {
        DateTimeFormatter formatter = new DateTimeFormatterBuilder().appendLiteral('a').toFormatter();
        assertThrows(IllegalArgumentException.class, () -> {
            formatter.parseInto(null, "abc", 0);
        });
    }

    @Test
    public void testParseInto_StandardParsing() {
        // Using a real formatter to avoid complex mocking of the internal parser logic
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendPattern("yyyyMMdd")
                .toFormatter();

        ReadWritableInstant instant = new ReadWritableInstant(new LocalDateTime(2023, 1, 1, 0, 0));
        String text = "20230101";
        int position = 0;

        int newPos = formatter.parseInto(instant, text, position);

        assertEquals(8, newPos);
        assertEquals(2023, instant.getChronology().year().get(instant.getMillis()));
    }

    @Test
    public void testParseInto_WithOffsetParsedTrue() {
        // Mocking dependencies to hit the iOffsetParsed branch
        DateTimeParser mockParser = mock(DateTimeParser.class);
        DateTimeFormatter formatter = mock(DateTimeFormatter.class);
        ReadWritableInstant instant = mock(ReadWritableInstant.class);
        Chronology chrono = DateTimeZone.UTC.getChronology();

        when(instant.getMillis()).thenReturn(0L);
        when(instant.getChronology()).thenReturn(chrono);
        when(chrono.getZone().getOffset(0L)).thenReturn(0);

        // We need to trigger the logic where iOffsetParsed is true
        // Since we can't easily inject private fields via Mockito, 
        // we use the builder to set the state.
        DateTimeFormatter offsetFormatter = new DateTimeFormatterBuilder()
                .appendPattern("yyyyMMddHHmmssZ")
                .withOffsetParsed()
                .toFormatter();

        // Using real objects for the complex internal state
        ReadWritableInstant realInstant = new ReadWritableInstant(new LocalDateTime(2023, 1, 1, 12, 0));
        String text = "20230101120000+0500";

        int newPos = offsetFormatter.parseInto(realInstant, text, 0);

        assertEquals(17, newPos);
        // Verify zone was updated via the offset
        assertEquals(DateTimeZone.forOffsetHours(5), realInstant.getZone());
    }

    @Test
    public void testParseInto_WithZoneSet() {
        DateTimeZone customZone = DateTimeZone.forID("Asia/Tokyo");
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendPattern("yyyyMMdd")
                .withZone(customZone)
                .toFormatter();

        ReadWritableInstant instant = new ReadWritableInstant(new LocalDateTime(2023, 1, 1, 0, 0));
        String text = "20230101";

        formatter.parseInto(instant, text, 0);

        assertEquals(customZone, instant.getZone());
    }

    @Test
    public void testParseInto_WithBucketZoneNotOffset() {
        // Test the branch: else if (bucket.getZone() != null)
        // This happens when the parser sets a zone in the bucket but iOffsetParsed is false
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendPattern("yyyyMMdd")
                .toFormatter();

        // We use a pattern that might trigger zone changes if the parser implementation allows
        // In Joda, standard patterns usually don't set zone unless Z or z is used.
        // To strictly test the branch, we rely on the fact that if the parser 
        // implementation provided by the builder sets a zone in the bucket.

        ReadWritableInstant instant = new ReadWritableInstant(new LocalDateTime(2023, 1, 1, 0, 0));
        String text = "20230101";

        int newPos = formatter.parseInto(instant, text, 0);
        assertEquals(8, newPos);
    }

    /**
     * Helper implementation of ReadWritableInstant since it's an interface 
     * required by the method signature.
     */
    private static class ReadWritableInstant implements org.joda.time.ReadableInstant {
        private long millis;
        private Chronology chronology;
        private DateTimeZone zone;

        public ReadWritableInstant(LocalDateTime dt) {
            this.millis = dt.getMillis();
            this.chronology = dt.getChronology();
            this.zone = dt.getZone();
        }

        public long getMillis() { return millis; }
        public Chronology getChronology() { return chronology; }
        public DateTimeZone getZone() { return zone; }

        public void setChronology(Chronology chronology) { this.chronology = chronology; }
        public void setZone(DateTimeZone zone) { this.zone = zone; }

        // Required by interface but not used in parseInto logic directly via setter
        public void setMillis(long millis) { this.millis = millis; }
    }
}
